INSERT INTO public.cms_stories (name, location, category, short_story, full_story, amount_raised, goal, donors_count, is_published, display_order, image_url)
VALUES
('Children''s Hope Program', 'Poland', 'child', 'Thanks to generous donors, children in conflict-affected areas are finding joy and normalcy through play, therapy, and community support activities.', 'Thanks to generous donors, children in conflict-affected areas are finding joy and normalcy through play, therapy, and community support activities. Our program provides safe spaces where children can heal from trauma through structured play therapy, art workshops, and community building events.', 12400, 18000, 187, true, 12, NULL),
('Rural Family Support', 'Haiti', 'family', 'Families in rural Haiti are receiving essential food supplies and grocery coupons, helping them through some of the most difficult times they have ever faced.', 'Families in rural Haiti are receiving essential food supplies and grocery coupons, helping them through some of the most difficult times they have ever faced. With limited access to markets and rising food costs, these families rely on direct support to feed their children and maintain their health.', 8750, 15000, 134, true, 13, NULL),
('Hurricane Helene Relief', 'North Carolina, USA', 'emergency', 'After Hurricane Helene devastated communities in North Carolina, donors helped families rebuild with grocery support and essential supplies when they needed it most.', 'After Hurricane Helene devastated communities in North Carolina, donors helped families rebuild with grocery support and essential supplies when they needed it most. Entire neighborhoods were left without power, clean water, or access to food for weeks.', 21300, 25000, 312, true, 14, NULL),
('Children of Heroes', 'Ukraine', 'child', 'Children of fallen heroes in Ukraine are receiving nutrition, education supplies, and community care — ensuring they are never forgotten.', 'Children of fallen heroes in Ukraine are receiving nutrition, education supplies, and community care — ensuring they are never forgotten. These brave children have lost parents who gave everything for their country, and our program ensures they receive the support they deserve.', 16800, 20000, 245, true, 15, NULL);